# solution.py
def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line:
            l, r = map(int, line.split())
            offers.append((l, r))

    result = []
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)  # 1-indexed, with extra padding
        total_days = 0

        for l, r in offers:
            # Check length condition
            if r - l + 1 < x:
                continue

            # Check if all days in [l, r] are free
            is_free = True
            for d in range(l, r + 1):
                if occupied[d]:
                    is_free = False
                    break

            if is_free:
                # Accept the offer and mark days as occupied
                for d in range(l, r + 1):
                    occupied[d] = True
                total_days += (r - l + 1)

        result.append(str(total_days))

    return '\n'.join(result) + '\n'

