def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    events = []
    for i in range(len(lines)):
        parts = lines[i].split()
        if parts[0] == '1':
            events.append('change')
        elif parts[0] == '2':
            events.append(('visit', parts[1]))

    intervals = []
    current = []
    for event in events:
        if event == 'change':
            if current:
                intervals.append(current)
                current = []
        else:
            current.append(event[1])
    if current:
        intervals.append(current)

    friends = sorted(set(f for interval in intervals for f in interval))
    n_friends = len(friends)

    # Build conflict matrix
    conflict = [[False] * n_friends for _ in range(n_friends)]
    for interval in intervals:
        seen = {}
        for f in interval:
            idx = friends.index(f)
            if idx in seen:
                conflict[idx][seen[idx]] = conflict[seen[idx]][idx] = True
            seen[idx] = idx

    memo = {}

    def dfs(remaining, selected):
        if not remaining:
            return selected
        if state := (remaining, selected) in memo:
            return memo[state]

        # Find first free index
        idx = next(i for i, r in enumerate(remaining) if r)

        # Pruning: upper bound
        if selected + 1 + sum(remaining[idx+1:]) <= best_result:
            return selected

        # Option 1: Select idx (remove conflicting nodes)
        result = selected
        for j in range(idx + 1, n_friends):
            if remaining[j] and conflict[idx][j]:
                remaining[j] = False
        new_remaining = remaining[:]
        result = max(result, dfs(new_remaining, selected + 1))
        for j in range(idx + 1, n_friends):
            if conflict[idx][j]:
                remaining[j] = True

        # Option 2: Don't select idx
        remaining[idx] = False
        result = max(result, dfs(remaining, selected))
        remaining[idx] = True

        memo[state] = result
        return result

    best_result = 0

    def solve(mask):
        nonlocal best_result

        # Check if valid
        count = bin(mask).count('1')
        if count <= best_result:
            return

        # Verify
        for i in range(n_friends):
            if (mask >> i) & 1:
                for j in range(i + 1, n_friends):
                    if (mask >> j) & 1 and conflict[i][j]:
                        best_result = count
                        return

        best_result = max(best_result, count)

    if n_friends <= 20:
        # Brute force with early pruning
        for mask in range(1 << n_friends):
            if bin(mask).count('1') <= best_result:
                continue
            valid = True
            for i in range(n_friends):
                if (mask >> i) & 1:
                    for j in range(i + 1, n_friends):
                        if (mask >> j) & 1 and conflict[i][j]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                best_result = max(best_result, bin(mask).count('1'))
    else:
        # Branch and bound
        best_result = 0

        def search(idx, mask):
            nonlocal best_result
            if idx == n_friends:
                best_result = max(best_result, bin(mask).count('1'))
                return

            # Try including idx
            include = mask | (1 << idx)
            if bin(include).count('1') + (n_friends - 1 - idx) > best_result:
                search(idx + 1, include)

            # Try excluding idx
            search(idx + 1, mask)

        search(0, 0)

    return str(best_result)


