def solution(data):
    lines = data.strip().split('\n')
    n = int(lines[0].strip())
    if n == 1:
        return '0'
    a = list(map(int, lines[1].strip().split()))

    # Use stack-based greedy approach
    # Process from left to right, maintain decreasing stack
    total = 0
    stack = []

    for x in a:
        while stack and stack[-1] >= x and len(stack) < n - 2:
            top = stack.pop()
            if stack:
                total += min(stack[-1], top)
            else:
                total += top
        stack.append(x)

    # Final processing for remaining elements in stack
    # Remove all except the last one
    while len(stack) > 2:
        total += min(stack[len(stack)-2], stack[-1])
        stack.pop()

    # The last element we remove gets 0 points (only 1 neighbor left)

    return str(total)

import heapq
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))

    start = int(lines[1 + m])

    # Adjacency list for Dijkstra
    adj = defaultdict(list)
    for u, v, w, idx in edges:
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    # Dijkstra's algorithm
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
            elif dist[u] + w == dist[v] and w < float('inf'):
                # We need to handle this properly - but actually for edge selection, 
                # we just need to check the condition later
                pass

    # For each vertex (except start), find the minimum weight edge that satisfies shortest path
    # The condition is: dist[p] + w == dist[v]
    selected_edges = []
    total_weight = 0

    for u, v, w, idx in edges:
        # Check if this edge can be used (going from v to u in shortest path tree)
        if dist[v] <= dist[u] and dist[u] + w == dist[v]:
            if idx not in [e[2] for e in selected_edges] and v != start:
                # Check if v is not yet covered
                pass
        # Check if this edge can be used (going from u to v in shortest path tree)
        if dist[u] <= dist[v] and dist[v] + w == dist[u]:
            if u == start:
                pass

    # Better approach: for each vertex v (except start), find min weight parent edge
    # where dist[parent] + w == dist[v]
    min_edge = {}  # v -> (min_weight, edge_idx)

    for u, v, w, idx in edges:
        # This edge can be parent edge for v if: dist[u] + w == dist[v]
        if dist[u] + w == dist[v]:
            if v not in min_edge or w < min_edge[v][0]:
                min_edge[v] = (w, idx)
        # This edge can also be parent edge for u if: dist[v] + w == dist[u]
        if dist[v] + w == dist[u]:
            if u not in min_edge or w < min_edge[u][0]:
                min_edge[u] = (w, idx)

    # Now select edges
    for v, (w, idx) in min_edge.items():
        if v != start:
            total_weight += w
            selected_edges.append(idx)

    # Convert to string
    output = f"{total_weight}\n{' '.join(map(str, sorted(selected_edges)))} "
    return output

from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        self.level = level
        return level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        max_f = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_f += pushed
        return max_f

