def solution(s):
    """
    Determine if the sequence is a geometric progression, or can become one
    by deleting a single element.
    """
    lines = s.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return '0\n'
    arr = list(map(int, lines[1].split()))

    def is_gp(seq):
        """Check if a sequence forms a geometric progression."""
        length = len(seq)
        if length <= 2:
            return True

        # Handle zeros carefully
        if seq[0] == 0:
            if seq[1] == 0:
                # All elements must be 0 for [0, 0, ...] to be a GP
                return all(x == 0 for x in seq)
            else:
                # [0, non-zero, ...] is not a valid GP
                return False

        if seq[1] == 0:
            # [non-zero, 0, ...] where non-zero != 0 is not a valid GP
            return False

        # All elements are non-zero, check ratio
        ratio = float(seq[1]) / float(seq[0])
        for i in range(2, length):
            expected = seq[i - 1] * ratio
            if abs(seq[i] - expected) > 1e-7:
                return False
        return True

    # Check if the sequence itself is a geometric progression
    if is_gp(arr):
        return '0\n'

    # Try removing each element and check if the result is a GP
    for i in range(n):
        new_arr = arr[:i] + arr[i + 1:]
        if is_gp(new_arr):
            return '1\n'

    return '2\n'

