import sys

def kmp_failure(virus):
    v_len = len(virus)
    if v_len == 0:
        return [0]
    failure = [0] * v_len
    k = 0
    for q in range(1, v_len):
        while k > 0 and virus[k] != virus[q]:
            k = failure[k - 1]
        if virus[k] == virus[q]:
            k += 1
        failure[q] = k
    return failure

def get_new_state(k, char, virus, failure):
    while k > 0 and virus[k] != char:
        k = failure[k - 1]
    if virus[k] == char:
        k += 1
    return k

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return "0"
    s1, s2, virus = lines[0], lines[1], lines[2]

    n, m, v_len = len(s1), len(s2), len(virus)

    if v_len == 0:
        return ""

    failure = kmp_failure(virus)

    # dp[i][j][k] = maximum length of valid LCS with k virus prefix matched
    dp = [[[-1] * v_len for _ in range(n + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 0

    # To reconstruct the solution, we store choices
    parent = [[[None, None, None] for _ in range(v_len)] for _ in range(n + 1)] for _ in range(m + 1)]

    INF = float('inf')
    dp_table = [[[-INF] * v_len for _ in range(n + 1)] for _ in range(m + 1)]
    dp_table[0][0][0] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len):
                if dp_table[i][j][k] < 0:
                    continue

                # Option 1: skip s1[i]
                if i < n:
                    new_k = get_new_state(k, s1[i], virus, failure)
                    if new_k < v_len:
                        if dp_table[i][j][k] + 1 > dp_table[i + 1][j][new_k]:
                            dp_table[i + 1][j][new_k] = dp_table[i][j][k]
                            parent[i + 1][j][new_k] = (0, 'skip_s1')

                # Option 2: skip s2[j]
                if j < m:
                    new_k = get_new_state(k, s2[j], virus, failure)
                    if new_k < v_len:
                        if dp_table[i][j][k] + 1 > dp_table[i][j + 1][new_k]:
                            dp_table[i][j + 1][new_k] = dp_table[i][j][k] + 1
                            parent[i][j + 1][new_k] = (0, 'skip_s2')

                # Option 3: match s1[i] == s2[j]
                if i < n and j < m and s1[i] == s2[j]:
                    new_k = get_new_state(k, s1[i], virus, failure)
                    if new_k < v_len:
                        if dp_table[i][j][k] + 1 > dp_table[i + 1][j + 1][new_k]:
                            dp_table[i + 1][j + 1][new_k] = dp_table[i][j][k] + 1
                            parent[i + 1][j + 1][new_k] = (1, s1[i])

    max_len = 0
    final_k = 0
    for k in range(v_len):
        if dp_table[n][m][k] > max_len:
            max_len = dp_table[n][m][k]
            final_k = k

    if max_len == 0:
        return "0"

    # Reconstruct solution
    i, j, k = n, m, final_k
    result = []

    while i > 0 or j > 0:
        p = parent[i][j][k]
        if p is None:
            break

        if p[1] == 'skip_s1':
            i -= 1
        elif p[1] == 'skip_s2':
            j -= 1
        else:  # match
            result.append(p[1])
            i -= 1
            j -= 1

    return ''.join(reversed(result))

