def solve_system(mat, n_nodes):
    """Gaussian elimination with checks"""
    if not mat:
        return [0.0] * n_nodes

    mat = [row[:] for row in mat]
    pivot_row = 0
    m = len(mat[0]) - 1

    for col in range(m):
        if pivot_row >= len(mat):
            break

        max_r = pivot_row
        for r in range(pivot_row + 1, len(mat)):
            if abs(mat[r][col]) > abs(mat[max_r][col]):
                max_r = r

        if abs(mat[max_r][col]) < 1e-9:
            continue

        mat[pivot_row], mat[max_r] = mat[max_r], mat[pivot_row]

        pivot = mat[pivot_row][col]
        for j in range(col, m + 1):
            mat[pivot_row][j] /= pivot

        for r in range(len(mat)):
            if r != pivot_row and abs(mat[r][col]) > 1e-9:
                factor = mat[r][col]
                for j in range(col, m + 1):
                    mat[r][j] -= factor * mat[pivot_row][j]

        pivot_row += 1

    for r in range(pivot_row, len(mat)):
        if abs(mat[r][-1]) > 1e-9:
            return None

    return [0.0] * n_nodes

def results(node_val, n):
    return "YES\n" + " ".join(f"{node_val[i]:.6f}" for i in range(1, n + 1))

