    s = lines[1]

    # dp[current_consecutive] = set of all achievable max consecutive N values
    # Initialize: before any characters, we have 0 consecutive with max 0
    dp = {0: {0}}

    for char in s:
        new_dp = defaultdict(set)

        for length, max_vals in dp.items():
            if char == 'Y':
                # Must reset consecutive count to 0
                # The max stays the same
                for mv in max_vals:
                    new_dp[0].add(mv)
            elif char == 'N':
                # Must extend consecutive count
                # Update the maximum if needed
                for mv in max_vals:
                    new_mv = max(mv, length + 1)
                    new_dp[length + 1].add(new_mv)
            else:  # char == '?'
                # Can be 'Y': reset consecutive count to 0
                for mv in max_vals:
                    new_dp[0].add(mv)
                # Can be 'N': extend consecutive count
                for mv in max_vals:
                    new_mv = max(mv, length + 1)
                    new_dp[length + 1].add(new_mv)

        dp = new_dp

    # Collect all achievable maximum values from all possible current consecutive lengths
    all_max_values = set()
    for max_vals in dp.values():
        all_max_values.update(max_vals)

    return "YES\n" if k in all_max_values else "NO\n"

