def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = [int(x) for x in lines[1].split()]
    m = int(lines[2])
    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by strength descending, keep track of original indices
    heroes = sorted(range(n), key=lambda i: strengths[i], reverse=True)

    # State for DP: (step, available_heroes_indices, team1_score, team2_score)
    # We use a frozenset for available heroes for memoization

    @lru_cache(maxsize=None)
    def dp(step, available, t1, t2):
        if step == m:
            return t1 - t2

        action, team = actions[step]
        available_list = available

        if action == 'p':
            if team == 1:
                new_t1 = t1
                new_t2 = t2
            else:
                new_t1 = t1
                new_t2 = t2

            # Each team wants to maximize their own total strength
            # This is equivalent to maximizing (t1 - t2) for team 1
            # and minimizing (t1 - t2) for team 2

            if not available_list:
                return t1 - t2

            best = float('-inf') if team == 1 else float('inf')

            for i in range(len(heroes)):
                if i in available_list:
                    val = strengths[heroes[i]]
                    nt1, nt2 = new_t1, new_t2
                    if team == 1:
                        nt1 = nt1 + val
                    else:
                        nt2 = nt2 + val

                    res = dp(step + 1, frozenset(available_list) - {i}, nt1, nt2)
                    if team == 1:
                        best = max(best, res)
                    else:
                        best = min(best, res)

            return best
        else:  # ban
            if not available_list:
                return t1 - t2

            best = float('-inf') if team == 1 else float('inf')

            for i in range(len(heroes)):
                if i in available_list:
                    res = dp(step + 1, frozenset(available_list) - {i}, t1, t2)
                    if team == 1:
                        best = max(best, res)
                    else:
                        best = min(best, res)

            return best

    initial_available = frozenset(range(len(heroes)))
    return str(dp(0, initial_available, 0, 0))

