        """Check if assignment is stable (no blocking pairs)"""
        for i in range(n):
            my_partner = assignment[i]  # city i's partner
            for k in range(n):
                if i == k:
                    continue
                other_partner = assignment[k]

                # If city i and city k are already partners, skip
                if other_partner == i:
                    continue

                # Check if both i and k would prefer each other over current partners
                if costs[i][k] < costs[i][my_partner] and costs[k][i] < costs[k][other_partner]:
                    return False
        return True

    def find_stable_matching():
        """Try to find a stable matching using random greedy approach"""
        for attempt in range(20000):  # Try many random orderings
            assignment = [None] * n
            used = [False] * n

            # Random order of cities to process
            cities = list(range(n))
            random.shuffle(cities)

            for i in cities:
                if used[i]:
                    continue
                # Find first available partner
                for k in cities:
                    if k != i and not used[k]:
                        assignment[i] = k
                        assignment[k] = i
                        used[i] = True
                        used[k] = True
                        break

            # Check if all cities are matched
            if all(a is not None for a in assignment):
                if is_stable(assignment):
                    return assignment

        return None

    # Find stable matching
    result = find_stable_matching()

