                        new_path = path + d
                        if nr == end_r and nc == end_c:
                            return new_path
                        visited.add((nr, nc))
                        queue.append((nr, nc, new_path))
        return None

    # Turn off start light if present
    if grid[curr_x][curr_y] == 1:
        actions.append('2')
        grid[curr_x][curr_y] = 0

    visited_new = set()
    if (curr_x, curr_y) in lit_cells:
        visited_new.add((curr_x, curr_y))

    while lit_cells:
        target_r, target_c = lit_cells.pop()
        lit_cells.add((target_r, target_c))  # Keep it if not yet visited

        if (target_r, target_c) in visited_new:
            continue

        path = bfs(curr_x, curr_y, target_r, target_c)

        if path is None:
            return "NO"

        # Follow path
        for d in path:
            dr, dc = 0, 0
            if d == 'U': dr = -1
            elif d == 'D': dr = 1
            elif d == 'L': dc = -1
            elif d == 'R': dc = 1
            actions.append(d)
            curr_x += dr
            curr_y += dc

        # Turn off light
        if grid[target_r][target_c] == 1:
            actions.append('2')
            grid[target_r][target_c] = 0

        visited_new.add((target_r, target_c))
        lit_cells.discard((target_r, target_c))

    # Return to start
    path = bfs(curr_x, curr_y, start_x, start_y)
    if path is None:
        return "NO"

    actions.extend(path)

    if len(actions) > 3 * 10**6:
        return "NO"

    return "YES\n" + "".join(actions)

