import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    line_idx = 1

    for i in range(1, m + 1):
        if line_idx >= len(lines):
            break
        line = lines[line_idx]
        line_idx += 1
        if not line.strip():
            continue
        try:
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)
        except ValueError:
            break

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            count = 0
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(count)

    # Check for lucky numbers - boolean
    def is_lucky(num):
        return all(d in '47' for d in str(num))

    # Precompute lucky numbers up to n
    lucky_numbers = [l for l in range(1, n + 1) if is_lucky(l)]
    lucky_set = set(lucky_numbers)
    max_lucky = max(lucky_numbers) if lucky_numbers else n

    # Check if any component is already lucky
    if component_sizes:
        for size in component_sizes:
            if is_lucky(size):
                return "0\n"

    if not component_sizes:
        return "-1\n"

    # Group component sizes for efficiency
    from collections import Counter
    size_counts = Counter(component_sizes)

    # dp[sum] = minimum number of components to achieve that sum
    dp = {0: 0}

    for size, count in size_counts.items():
        for _ in range(count):
            updates = {}
            # Create new sums by adding 'size' to each existing reachable sum
            for s, val in dp.items():
                new_s = s + size
                if new_s <= max_lucky:
                    # Only keep if this is a better way to reach new_s
                    if new_s not in updates or val + 1 < updates[new_s]:
                        updates[new_s] = val + 1
            # Apply updates atomically to avoid using updated values in same component group
            dp.update(updates)

    # Find minimum number of roads needed
    ans = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp:
            roads = dp[lucky] - 1
            if roads >= ans:
                ans = roads

    if ans == float('inf'):
        return "-1\n"
    else:
        return f"{ans}\n"


