        generated = set()
        for k in range(n):
            val = (x + k * d) % m
            generated.add(val)
        if len(generated) == n and set(a) == generated:
            return f"{x} {d}\n"
        return "-1\n"

    # General case: n < m
    inv = mod_inverse(n - 1, m)
    if inv is None:
        return "-1\n"
    d = (span * inv) % m

    if d == 0:
        return "-1\n"

    # Try all possible starting positions
    for x in a:
        generated = set()
        valid = True
        for k in range(n):
            val = (x + k * d) % m
            if val in generated:
                valid = False
                break
            generated.add(val)
        if valid and set(a) == generated:
            return f"{x} {d}\n"

    return "-1\n"

