    for i in range(1, m + 1):
        a, b, l = map(int, data[i].split())
        adj[a].append((b, l))

    # Kosaraju's algorithm for SCC decomposition
    visited = [False] * (n + 1)
    order = []

    def dfs1(u):
        visited[u] = True
        for v, _ in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs1(i)

    # Build reverse graph
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v, l in adj[u]:
            rev_adj[v].append(u)

    scc_id = [0] * (n + 1)
    visited = [False] * (n + 1)
    scc_count = 0

    for u in reversed(order):
        if not visited[u]:
            scc_count += 1
            stack = [u]
            visited[u] = True
            while stack:
                curr = stack.pop()
                scc_id[curr] = scc_count
                for v, _ in rev_adj[curr]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

    # For each SCC, compute GCD of all cycle lengths
    scc_gcd = [0] * (scc_count + 1)

    for scc_idx in range(1, scc_count + 1):
        # Find all nodes in this SCC
        scc_nodes = []
        for v in range(1, n + 1):
            if scc_id[v] == scc_idx:
                scc_nodes.append(v)

        if not scc_nodes:
            continue

        # Pick an arbitrary root in this SCC
        root = scc_nodes[0]

        # BFS from root to compute distances
        dist = {root: 0}
        parent = {root: -1}
        queue = deque([root])

        while queue:
            u = queue.popleft()
            for v, w in adj[u]:
                if v not in dist and scc_id[v] == scc_id[root]:
                    dist[v] = dist[u] + w
                    parent[v] = u
                    queue.append(v)

        # Compute GCD of all cycle lengths
        g = 0
        for u in scc_nodes:
            if parent[u] != -1:
                for v, w in adj[parent[u]]:
                    if v == u and scc_id[v] == scc_id[root]:
                        total = dist[u] + w + dist[root]
                        g = math.gcd(g, total)
                        break

        scc_gcd[scc_idx] = g if g != 0 else 0

    # Answer queries
    q_rows = len(data) - (m + 1)
    q = int(data[m + 1])

    results = []
    for i in range(q):
        v, s, t = map(int, data[m + 2 + i].split())
        scc = scc_id[v]
        g = scc_gcd[scc]

        if s == 0:
            results.append("YES")
        elif g == 0:
            if s % t == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            if s % g == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

