def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO\n"

    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    val_to_idx = {v: i for i, v in enumerate(p)}

    parent = list(range(n))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while x != root:
            next_node = parent[x]
            parent[x] = root
            x = next_node
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build unions for a and b constraints
    for i in range(n):
        x = p[i]

        idx_a = val_to_idx.get(a - x)
        if idx_a is not None and idx_a != i:
            union(i, idx_a)

        idx_b = val_to_idx.get(b - x)
        if idx_b is not None and idx_b != i:
            union(i, idx_b)

    # Collect values and indices per component
    comp_vals = defaultdict(set)
    comp_indices = defaultdict(list)

    for i in range(n):
        root = find(i)
        comp_vals[root].add(p[i])
        comp_indices[root].append(i)

    result = [0] * n

    for root in comp_vals:
        vals = comp_vals[root]

        can_A = True
        for x in vals:
            if x * 2 != a and (a - x) not in val_to_idx:
                can_A = False
                break

        can_B = True
        for x in vals:
            if x * 2 != b and (b - x) not in val_to_idx:
                can_B = False
                break

        if not can_A and not can_B:
            return "NO\n"

        if can_A:
            for i in comp_indices[root]:
                result[i] = 0
        else:
            for i in comp_indices[root]:
                result[i] = 1

    return "YES\n" + " ".join(map(str, result)) + " \n"

