def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "0"

    MOD = 10**9 + 7
    X_str = input_str
    L = len(X_str)
    digits = [int(c) for c in X_str]

    if int(X_str) == 0:
        return "0"

    def compute_F(d):
        # For digit d, compute Σ 10^(count of digits < d in n) for n from 1 to X
        from functools import lru_cache

        @lru_cache(None)
        def dp(idx, started, count_less_d, tight):
            if idx == L:
                return 1 if started else 0

            limit = digits[idx] if tight else 9
            total_ans = 0
            total_ways = 0

            for digit in range(limit + 1):
                new_tight = tight and (digit == limit)
                new_started = started or (digit > 0)

                if not started:
                    # Leading zero, no contribution to count
                    ways, ans = dp(idx + 1, False, 0, new_tight)
                else:
                    # We've started the number
                    if digit < d:
                        ways, ans = dp(idx + 1, True, count_less_d + 1, new_tight)
                    else:
                        ways, ans = dp(idx + 1, True, count_less_d, new_tight)

                total_ways = (total_ways + ways) % MOD
                total_ans = (total_ans + ways * ans) % MOD

            return total_ways, total_ans

        return compute_F_single(0, False, 0, True)

    def compute_F_single(idx, started, count_less_d, tight):
        if idx == L:
            return 1 if started else 0

        limit = digits[idx] if tight else 9
        total_ans = 0
        total_ways = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit > 0)

            if not started:
                ways, ans = compute_F_single(idx + 1, False, 0, new_tight)
            else:
                if digit < d:
                    ways, ans = compute_F_single(idx + 1, True, count_less_d + 1, new_tight)
                else:
                    ways, ans = compute_F_single(idx + 1, True, count_less_d, new_tight)

            total_ways = (total_ways + ways) % MOD
            total_ans = (total_ans + ways * ans) % MOD

        return total_ways, total_ans

    # Compute total sum
    total = 0
    for d in range(1, 10):
        ways, ans = compute_F_single(0, False, 0, True)
        if started or True:
            contribution = d * ans % MOD
            total = (total + contribution) % MOD

    return str(total)

