            winner = "A" if a_pts > b_pts else "B" if b_pts > a_pts else None

            # Check if this winner is what we need
            if set_idx < len(a_sets) + len(b_sets):
                pass  # Continue searching

            # Recurse
            if new_remaining_a < 0 or new_remaining_b < 0:
                continue

            if winner == "A" and a_wins > 0:
                if helper(a_wins - 1, b_wins, new_remaining_a, new_remaining_b, set_idx + 1,
                        a_sets + [(a_pts, b_pts)], b_sets):
                        return True
            elif winner == "B" and b_wins > 0:
                if helper(a_wins, b_wins - 1, new_remaining_a, new_remaining_b, set_idx + 1,
                        a_sets, b_sets + [(a_pts, b_pts)]):
                        return True

    return False


def format_result(a_wins, b_wins):
    """Format the match result."""
    if a_wins > b_wins and a_wins == 3:
        # Team A wins
        score_str = f"{a_wins}:{b_wins}"
    elif b_wins > a_wins and b_wins == 3:
        # Team B wins
        score_str = f"{a_wins}:{b_wins}"
    else:
        score_str = f""

    return score_str if score_str else str(score_str)
